func TestBatchCollectionDeadline(t *testing.T) {
	for _, preparation := range []time.Duration{6 * time.Millisecond, 12 * time.Millisecond} {
		t.Run(preparation.String(), func(t *testing.T) {
			synctest.Test(t, func(t *testing.T) {
				w := NewWorker()
				defer w.Close()
				prepared := false
				batch := &Batch{CollectWindow: 8 * time.Millisecond, CollectFromStart: true, CanWait: func() bool { return prepared }}
				batch.RunReady = func(ops []BatchOperation, collect func() []BatchOperation) []BatchResult {
					results := make([]BatchResult, 0, len(ops))
					for i := 0; i < len(ops); i++ {
						v, e := ops[i].Run()
						prepared = true
						results = append(results, BatchResult{v, e})
						if i == len(ops)-1 {
							ops = append(ops, collect()...)
						}
					}
					return results
				}
				start := time.Now()
				_, err := w.SubmitBatch(context.Background(), batch, 1, func() (any, error) { time.Sleep(preparation); return nil, nil })
				if err != nil || time.Since(start) != max(8*time.Millisecond, preparation) {
					t.Fatal("preparation not counted", err, time.Since(start))
				}
			})
		})
	}
}

func TestBatchCollectionDeadlineJoinsPreparedFollowup(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		w := NewWorker()
		defer w.Close()
		prepared := false
		committed := false
		count := 0
		batch := &Batch{AcrossKeys: true, CollectWindow: 8 * time.Millisecond, CollectFromStart: true, CanWait: func() bool { return prepared }}
		batch.RunReady = func(ops []BatchOperation, collect func() []BatchOperation) []BatchResult {
			var results []BatchResult
			for i := 0; i < len(ops); i++ {
				v, e := ops[i].Run()
				prepared = true
				results = append(results, BatchResult{v, e})
				if i == len(ops)-1 {
					ops = append(ops, collect()...)
				}
			}
			count = len(ops)
			committed = true
			return results
		}
		done := make(chan struct{})
		go func() {
			defer close(done)
			time.Sleep(7 * time.Millisecond)
			_, err := w.SubmitBatch(context.Background(), batch, 2, func() (any, error) { time.Sleep(3 * time.Millisecond); return nil, nil })
			if err != nil {
				t.Error(err)
			}
		}()
		start := time.Now()
		_, err := w.SubmitBatch(context.Background(), batch, 1, func() (any, error) { time.Sleep(6 * time.Millisecond); return nil, nil })
		<-done
		if err != nil || !committed || count != 2 || time.Since(start) != 10*time.Millisecond {
			t.Fatal("followup split or extra wait", err, count, time.Since(start))
		}
	})
}

